44:const enemies=[];function makeEnemy(x,z){const g=new THREE.Group();const armor=mat(0x654e38),skin=mat(0x7c4b32);const legs=new THREE.Mesh(new THREE.CapsuleGeometry(.25,.65,4,6),armor);legs.position.y=.7;g.add(legs);const chest=new THREE.Mesh(new THREE.CapsuleGeometry(.48,.65,4,8),armor);chest.position.y=1.55;chest.castShadow=true;g.add(chest);const head=new THREE.Mesh(new THREE.SphereGeometry(.34,10,8),skin);head.position.y=2.25;g.add(head);const horn=new THREE.Mesh(new THREE.ConeGeometry(.12,.55,5),mat(0xb4a56b));horn.position.set(0,2.55,0);horn.rotation.z=.15;g.add(horn);g.position.set(x,0,z);g.userData={hp:60,fire:Math.random()*2,hit:0};scene.add(g);enemies.push(g)}
